 "  \"notifications\": \"any notifications/* message is answered 202 with no body\",",
 "  \"batch\": \"a JSON-RPC array is answered as an array of the replies (notifications carry none)\",",
 "  \"modern\": {",
 "   \"_doc\": \"D3b: the stateless revision on the same endpoint. A request whose params._meta carries io.modelcontextprotocol/protocolVersion is served by it (no initialize, no session); initialize and every other request keep the handshake revision's answers\",",
 "   \"protocols\": [",
 "    \"2026-07-28\"",
 "   ],",
 "   \"discover\": \"server/discover answers before auth: {resultType: complete, supportedVersions, capabilities, instructions (initialize's own), ttlMs: 0, cacheScope: public, _meta: {io.modelcontextprotocol/serverInfo}}\",",
